"""Self-contained Datasheet MCP App."""

APP_HTML = r'''<!doctype html>
<html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workbench</title>
<style>:root{color-scheme:light;--bg:#f4f2ed;--panel:#fffefa;--ink:#22211f;--muted:#706d67;--line:#d5d0c7;--accent:#376c5a;--bad:#a44840;font:14px/1.45 Inter,system-ui,sans-serif}:root[data-theme=dark]{color-scheme:dark;--bg:#101112;--panel:#18191a;--ink:#ece9e2;--muted:#a19d95;--line:#353638;--accent:#87c4aa;--bad:#e17d72}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink)}header{display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid var(--line);background:var(--panel)}header div{flex:1}h1,h2,p{margin:0}h1{font-size:20px}.muted{color:var(--muted)}main{display:grid;grid-template-columns:minmax(260px,360px) 1fr;min-height:520px}aside,section{padding:14px}aside{border-right:1px solid var(--line)}textarea,input,button{width:100%;font:inherit;color:inherit;background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:8px}textarea{min-height:190px;resize:vertical;font:12px/1.45 ui-monospace,monospace}label{display:block;margin:10px 0 4px;color:var(--muted);font-size:12px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:9px}button{cursor:pointer;font-weight:650}button.primary{background:var(--accent);border-color:var(--accent);color:var(--bg)}pre{margin:0;min-height:390px;max-height:650px;overflow:auto;padding:14px;background:var(--panel);border:1px solid var(--line);border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace}.status{font:12px ui-monospace,monospace;color:var(--muted)}.status.bad{color:var(--bad)}@media(max-width:720px){main{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}}</style></head>
<body><header><div><h1>Workbench</h1><p class="muted">Preview, inspect, and profile governed tabular data</p></div><span id="status" class="status">connecting</span></header><main><aside><label for="csv">Inline CSV or replace it with an artifact URI in the JSON</label><textarea id="csv">city,value
San Salvador,12
New York,19
London,15</textarea><label for="column">Statistics column</label><input id="column" value="value"><div class="actions"><button id="preview" class="primary">Preview</button><button id="stats">Column stats</button><button id="profile">Full profile</button><button id="reports">Reports</button></div></aside><section><pre id="output">Ready to inspect the sample dataset.</pre></section></main>
<script>const $=id=>document.getElementById(id);let next=1;const pending=new Map(),handlers=new Map(),post=m=>parent.postMessage(m,"*");addEventListener("message",e=>{const m=e.data;if(!m||m.jsonrpc!=="2.0")return;if(m.id!==undefined&&(m.result!==undefined||m.error!==undefined)){const w=pending.get(m.id);if(!w)return;pending.delete(m.id);m.error?w.reject(new Error(m.error.message||"host error")):w.resolve(m.result);return}handlers.get(m.method)?.(m.params,m.id)});const bridge={request(method,params){const id=next++;post({jsonrpc:"2.0",id,method,params});return new Promise((resolve,reject)=>pending.set(id,{resolve,reject}))},notify:(method,params)=>post({jsonrpc:"2.0",method,params}),on:(method,fn)=>handlers.set(method,fn)};const structured=v=>v?.structuredContent??v?.structured_content??v;const taskId=v=>v?.taskId??v?.task_id??v?._meta?.["io.modelcontextprotocol/task"]?.taskId;const state=v=>v?.status??v?.state??v?.task?.status;const terminal=v=>["completed","failed","cancelled"].includes(String(v||"").toLowerCase());function show(v){$("output").textContent=JSON.stringify(structured(v),null,2);bridge.notify("ui/notifications/size-changed",{height:Math.ceil(document.documentElement.scrollHeight)})}async function call(name,args){$("status").textContent=`running ${name}`;try{let result=await bridge.request("tools/call",{name,arguments:args}),id=taskId(result);if(id)for(let i=0;i<240;i++){result=await bridge.request("tasks/get",{taskId:id});show(result);if(terminal(state(result)))break;await new Promise(r=>setTimeout(r,500))}show(result);$("status").textContent="ready"}catch(error){$("status").textContent="failed";$("status").className="status bad";$("output").textContent=error.message}}async function reports(){try{const result=await bridge.request("resources/read",{uri:"datasheet://reports"}),content=result?.contents?.[0];show(JSON.parse(content?.text||"[]"))}catch(error){$("output").textContent=error.message}}$("preview").onclick=()=>call("preview_dataset",{inline_csv:$("csv").value,rows:20});$("stats").onclick=()=>call("column_stats",{inline_csv:$("csv").value,column:$("column").value});$("profile").onclick=()=>call("profile_dataset",{inline_csv:$("csv").value,artifact:true,histogram_bins:20});$("reports").onclick=reports;bridge.on("ui/notifications/host-context-changed",p=>document.documentElement.dataset.theme=(p?.hostContext||p)?.theme==="light"?"light":"dark");bridge.on("ui/resource-teardown",(_p,id)=>id!==undefined&&post({jsonrpc:"2.0",id,result:{}}));(async()=>{try{const init=await bridge.request("ui/initialize",{protocolVersion:"2026-01-26",appInfo:{name:"datasheet-workbench",version:"1.0.0"},appCapabilities:{availableDisplayModes:["inline"]}});document.documentElement.dataset.theme=init?.hostContext?.theme==="light"?"light":"dark";bridge.notify("ui/notifications/initialized",{});$("status").textContent="ready"}catch(error){$("status").textContent="unavailable";$("output").textContent=error.message}})();</script></body></html>'''
